        () => { const [a, b] = subOver10(); return { t: `Có ${a} quả bóng bay và ${b} bạn. Mỗi bạn được lấy 1 quả bóng. Hỏi còn lại bao nhiêu quả bóng?`, a: a - b, w: [a + b, a - b + 1, b], u: 'quả', s: [`Có ${b} bạn lấy ${b} quả.`, `${a} − ${b} = ${a - b} (quả).`] }; }
