    { level: 3, name: 'Thành phần là số đặc biệt', fn() { const P = [['số tròn chục lớn nhất có hai chữ số', 90], ['số lớn nhất có hai chữ số', 99], ['số lớn nhất có hai chữ số khác nhau', 98], ['số tròn chục bé nhất có hai chữ số', 10]]; const Qs = [['số bé nhất có hai chữ số giống nhau', 11], ['số lớn nhất có một chữ số', 9], ['số bé nhất có hai chữ số', 10], ['số liền sau của 19', 20], ['số chẵn lớn nhất có một chữ số', 8]]; const p = pick(P), q = pick(Qs); if (p[1] === q[1]) return this.fn(); return Q({ text: `Số bị trừ là ${p[0]}, số trừ là ${q[0]}. Hiệu của hai số đó là:`, answer: p[1] - q[1], wrongs: [p[1] + q[1] > 120 ? p[1] - q[1] + 1 : p[1] + q[1], p[1] - q[1] + 10, p[1] - q[1] - 1], hint: 'Tìm số bị trừ và số trừ trước.', steps: [`Số bị trừ: ${p[1]}; số trừ: ${q[1]}.`, `${p[1]} − ${q[1]} = <b>${p[1] - q[1]}</b>.`] }); } }
