  X('g2_measure', [
    { level: 1, name: 'Đọc cân đĩa thăng bằng', fn() { const it = pick([['quả dưa hấu', '🍉'], ['con gà', '🐔'], ['quả bí ngô', '🎃'], ['nải chuối', '🍌'], ['túi gạo', '🛍️']]); const w = shuffle([1, 2, 3, 5]).slice(0, R(1, 2)); const tot = w.reduce((s, x) => s + x, 0); return Q({ text: `Cân thăng bằng. ${it[0][0].toUpperCase() + it[0].slice(1)} cân nặng mấy ki-lô-gam?`, answer: tot, wrongs: [tot + 1, tot - 1 || 4, w.length], unit: 'kg', hint: 'Cân thăng bằng thì hai bên nặng bằng nhau: cộng các quả cân.', steps: [`${w.map(x => x + ' kg').join(' + ')} = ${tot} kg.`, `${it[0]} nặng <b>${tot} kg</b>.`], visual: { type: 'balance', left: [it[1]], right: w.map(x => x + ' kg'), caption: 'Cân thăng bằng' } }); } },
    { level: 1, name: 'Giờ buổi chiều, buổi tối', fn() { const h = R(13, 23); const T = R(0, 1); const buoi = h <= 17 ? 'chiều' : 'tối'; if (T) return Q({ text: `<b>${h} giờ</b> còn gọi là mấy giờ ${buoi}?`, answer: h - 12, wrongs: [h - 10, h - 12 + 1, h % 10 || 3], unit: 'giờ', hint: 'Lấy số giờ trừ đi 12.', steps: [`${h} − 12 = ${h - 12}.`, `${h} giờ = <b>${h - 12} giờ ${buoi}</b>.`] }); return Q({ text: `<b>${h - 12} giờ ${buoi}</b> còn gọi là bao nhiêu giờ?`, answer: h, wrongs: [h - 12 + 10, h + 1, h - 1], unit: 'giờ', hint: 'Giờ buổi chiều, tối: cộng thêm 12.', steps: [`${h - 12} + 12 = <b>${h}</b>.`] }); } },
    { level: 1, name: 'Kim ngắn chỉ số mấy', fn() { const h = R(13, 23); const m = 0; return Q({ text: `Lúc <b>${h} giờ</b>, kim dài chỉ số <b>12</b>. Kim ngắn chỉ số mấy?`, answer: h - 12, wrongs: [h - 10, h - 12 + 1, (h - 12 + 6) % 12 || 12], hint: `${h} giờ = ${h - 12} giờ ${h <= 17 ? 'chiều' : 'tối'}.`, steps: [`${h} − 12 = ${h - 12}.`, `Kim ngắn chỉ số ${h - 12}.`, `Đáp án: <b>${h - 12}</b>.`], visual: { type: 'clock', h: h - 12, m } }); } },
    { level: 2, name: 'Ai sớm hơn, muộn hơn mấy phút', fn() { const [n1, n2] = two(); const h = R(6, 9); const ms = shuffle([0, 15, 30]).slice(0, 2); const d = Math.abs(ms[0] - ms[1]); const early = ms[0] < ms[1] ? n1 : n2; const f = (m) => m ? `${h} giờ ${m} phút` : `${h} giờ`; const act = pick(['thức dậy', 'đến trường', 'ăn sáng']); const ask = R(0, 1); return Q({ text: `${n1} ${act} lúc ${f(ms[0])}. ${n2} ${act} lúc ${f(ms[1])}. Bạn nào ${act} ${ask ? 'sớm' : 'muộn'} hơn và hơn bao nhiêu phút?`, answer: `${ask ? early : (early === n1 ? n2 : n1)}, ${d} phút`, options: [`${n1}, ${d} phút`, `${n2}, ${d} phút`, `${n1}, ${d + 15} phút`, `${n2}, ${d === 15 ? 30 : 15} phút`], hint: 'So sánh số phút (cùng một giờ).', steps: [`${f(ms[0])} và ${f(ms[1])} chênh nhau ${d} phút.`, `${early} ${act} sớm hơn → bạn kia muộn hơn.`, `Đáp án: <b>${ask ? early : (early === n1 ? n2 : n1)}, ${d} phút</b>.`] }); } },
    { level: 2, name: 'Mấy giờ nữa – lúc mấy giờ', fn() { const T = R(0, 1); if (T) { const s = R(6, 11), k = R(2, 7); const e = s + k; return Q({ text: `Bây giờ là ${s} giờ sáng. ${k} giờ nữa ${pick(NAMES)} tan học. Vậy ${pick(['bạn ấy', 'bạn'])} tan học lúc mấy giờ?`, answer: e, wrongs: [e - 12 > 0 ? e - 12 : e + 1, e + 1, s + k + 2], unit: 'giờ', hint: 'Cộng thêm số giờ.', steps: [`${s} + ${k} = <b>${e}</b> (giờ)${e > 12 ? ` — tức ${e - 12} giờ chiều` : ''}.`] }); } const s = R(6, 10), e = R(13, 18); const ee = e - 12; return Q({ text: `Từ ${s} giờ sáng đến ${ee} giờ chiều cùng ngày là bao nhiêu giờ?`, answer: e - s, wrongs: [Math.abs(ee - s) || 3, e - s + 1, e - s - 1], unit: 'giờ', hint: `${ee} giờ chiều = ${e} giờ.`, steps: [`${ee} giờ chiều = ${e} giờ.`, `${e} − ${s} = <b>${e - s}</b> (giờ).`] }); } },
    { level: 2, name: 'Lịch tháng – thứ mấy', fn() { const d1 = R(1, 20), dw = R(0, 6); const d2 = R(1, 30); if (d2 === d1) return this.fn(); const diff = d2 - d1; const w = ((dw + diff) % 7 + 7) % 7; const mo = R(1, 12); return Q({ text: `Ngày ${d1} tháng ${mo} là <b>${THU[dw]}</b>. Vậy ngày ${d2} tháng ${mo} cùng năm đó là thứ mấy?`, answer: THU[w], options: shuffle([THU[w], THU[(w + 1) % 7], THU[(w + 6) % 7], THU[(w + 3) % 7]]), hint: 'Mỗi tuần có 7 ngày: cùng thứ thì ngày cách nhau 7, 14, 21… ngày.', steps: [`Hai ngày cách nhau ${Math.abs(diff)} ngày = ${Math.floor(Math.abs(diff) / 7)} tuần và ${Math.abs(diff) % 7} ngày.`, `${THU[dw]} ${diff > 0 ? 'thêm' : 'lùi'} ${Math.abs(diff) % 7} ngày → <b>${THU[w]}</b>.`] }); } },
    { level: 2, name: 'Tuần trước – tuần sau', fn() { const d = R(8, 23); const T = pick([-1, 1]); const dw = R(0, 6); return Q({ text: `${THU[dw]} tuần này là ngày <b>${d}</b>. ${THU[dw]} tuần ${T > 0 ? 'sau' : 'trước'} là ngày bao nhiêu?`, answer: d + 7 * T, wrongs: [d + T, d + 7 * T + 1, d - 7 * T], hint: 'Một tuần có 7 ngày.', steps: [`${d} ${T > 0 ? '+' : '−'} 7 = <b>${d + 7 * T}</b>.`] }); } },
    { level: 2, name: 'Chọn can đủ số lít', fn() { const cans = shuffle([2, 3, 4, 5, 6, 7, 10]).slice(0, 5).sort((a, b) => a - b); const pairs = []; for (let i = 0; i < 5; i++) for (let j = i + 1; j < 5; j++) pairs.push([cans[i], cans[j]]); const p = pick(pairs); const t = p[0] + p[1]; const good = pairs.filter(q => q[0] + q[1] === t); if (good.length > 1) return this.fn(); const S = (q) => `Can ${q[0]} l và can ${q[1]} l`; const wr = shuffle(pairs.filter(q => q !== p)).slice(0, 3); return Q({ text: `Có các can chứa đầy nước mắm: <b>${cans.map(c => c + ' l').join('; ')}</b>. Để có <b>${t} l</b> nước mắm thì cần lấy nguyên hai can nào?`, answer: S(p), options: [S(p)].concat(wr.map(S)), hint: `Tìm hai số có tổng bằng ${t}.`, steps: [`${p[0]} l + ${p[1]} l = ${t} l.`, `Lấy <b>${S(p)}</b>.`] }); } },
    { level: 2, name: 'Tính ba số có đơn vị', fn() { const u = pick(['kg', 'l']); const a = R(20, 70), b = R(5, 30), c = R(5, 30); const T = pick([['+', '−'], ['−', '+'], ['−', '−']]); const x = T[0] === '+' ? a + b : a - b; const r = T[1] === '+' ? x + c : x - c; if (x > 99 || x < 0 || r < 0 || r > 99) return this.fn(); return Q({ text: `Tính: <b>${a} ${u} ${T[0]} ${b} ${u} ${T[1]} ${c} ${u} = ?</b>`, answer: r, wrongs: [r + 10, r - 1, T[1] === '+' ? Math.abs(x - c) : x + c], unit: u, hint: 'Tính từ trái sang phải, giữ nguyên đơn vị.', steps: [`${a} ${T[0]} ${b} = ${x}.`, `${x} ${T[1]} ${c} = <b>${r}</b> (${u}).`] }); } },
    { level: 3, name: 'Cân với các vật giống nhau', fn() { const n = R(2, 4), w = R(1, 4), k = pick([0, 1, 2]); const tot = n * w + k; if (tot > 15) return this.fn(); const it = pick([['quả lê', '🍐'], ['quả táo', '🍎'], ['bắp cải', '🥬'], ['quả cam', '🍊']]); const left = Array(n).fill(it[1]).concat(k ? [k + ' kg'] : []); return Q({ text: `Cân thăng bằng: bên trái có ${n} ${it[0]} như nhau${k ? ` và quả cân ${k} kg` : ''}; bên phải có quả cân <b>${tot} kg</b>. Mỗi ${it[0]} cân nặng mấy ki-lô-gam?`, answer: w, wrongs: [w + 1, tot - k, w + 2], unit: 'kg', hint: k ? `Bớt quả cân ${k} kg ở cả hai bên trước.` : 'Thử từng số: mấy cộng mấy (các số bằng nhau) bằng tổng?', steps: [k ? `${n} ${it[0]} nặng: ${tot} − ${k} = ${tot - k} (kg).` : `${n} ${it[0]} nặng ${tot} kg.`, `${Array(n).fill(w).join(' + ')} = ${n * w} → mỗi ${it[0]} nặng <b>${w} kg</b>.`], visual: { type: 'balance', left, right: [tot + ' kg'], caption: 'Cân thăng bằng' } }); } }
  ]);

